INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(12593, 'koKR', 'Na służbie Króla Lisza', 'Wszystko, czym jestem – gniew, okrucieństwo, zemstę – przekazuję tobie, $gmój wybrańcze:moja wybranko;. Obdarzyłem cię nieśmiertelnością, abyś $gzwiastował:zwiastowała; nową, mroczną erę Plagi.$B$BSpójrz teraz na ziemie pod nami. Szkarłatna Krucjata uwija się, by zniweczyć moje dzieło, a Świetlista Nadzieja wyzywająco stawia nam opór – skaza na tych Plagowiskach. Wszyscy oni muszą poznać cenę swojego nieposłuszeństwa.$B$BStaniesz się narzędziem mojej odpłaty. Gdzie stąpniesz, tam podąży zagłada. Idź teraz i sięgnij po swoje przeznaczenie, rycerzu śmierci.', 'Zamelduj się u instruktora Razuwiusza w Sercu Acherusu.$B', '', '', '', '', '', '', 0),
(12619, 'koKR', 'Zdobione runiczne ostrze', 'Najważniejszym elementem wyposażenia rycerza śmierci jest runiczne ostrze. To przez nie rycerz śmierci włada mocą mrozu, krwi i bezbożności. Runiczne ostrze służy mu też za naczynie, w którym gromadzi moc runiczną.$B$BNadszedł czas, byś $gstworzył:stworzyła; swoje pierwsze runiczne ostrze. Przeszukaj stojaki na broń na tym piętrze i znajdź wysłużony miecz. Gdy go znajdziesz, zanieś go do pobliskiej kuźni run i użyj jej, by stworzyć runiczne ostrze.', 'Przeszukaj stojaki na broń w Hebanowej Warowni, znajdź wysłużony miecz, a potem użyj go przy kuźni run, by wykuć miecz z runicznym ostrzem.$B$BZanieś miecz z runicznym ostrzem instruktorowi Razuwiuszowi w Hebanowej Warowni.', '', 'Wróć do instruktora Razuwiusza w Sercu Acherusu w Hebanowej Warowni.', '', '', '', '', 0),
(12636, 'koKR', 'Oko Acherusu', 'Oto Acherus, wspaniała cytadela śmierci! Nie ma sobie równych na tym świecie! Nawet potężny Naxxramas nie wytrzymałby bezpośredniego szturmu Hebanowej Warowni. Nad frontem nekropolii góruje wszechwidzące oko Acherusu. Dzięki niemu nasz pan widzi daleko w głąb terytoriów naszych wrogów. Co widzi oko, to widzi Król Lisz, a teraz nadszedł czas, byś i ty $gspojrzał:spojrzała; przez oko! Król Lisz cię wzywa, $N.$B$BIdź już! Cierp godnie, $gbracie:siostro;...$B', 'Zamelduj się u Króla Lisza w Hebanowej Warowni.', '', '', '', '', '', '', 0),
(12641, 'koKR', 'Śmierć nadchodzi z wysoka', 'Nad tym podestem góruje oko Acherusu. Za jego pomocą przywołasz sondę, której użyjesz, by zbadać umocnienia Szkarłatnej Krucjaty w Nowym Avalonie. Oko ma wiele mocy, które powinny ułatwić zdobycie tych informacji.$B$BUżyj syfonu oka, by zbadać kuźnię, ratusz, warownię i kaplicę. Mechanizmy sterujące okiem znajdują się po obu stronach tego podestu. Nie trać więcej czasu, $N.$B$BPlaga zawładnie tym miejscem. Tak rozkazuje Król Lisz!', 'Król Lisz rozkazuje ci użyć Oka Acherusu, by zbadać Szkarłatną Warownię, Kuźnię Nowego Avalonu, Ratusz Nowego Avalonu i Kaplicę Karmazynowego Płomienia.$B$BSterujesz Okiem Acherusu za pomocą mechanizmu sterującego Oka Acherusu.', '', 'Wróć do Króla Lisza w Hebanowej Warowni.', 'Kuźnia Nowego Avalonu zbadana', 'Ratusz Nowego Avalonu zbadany', 'Szkarłatna Warownia zbadana', 'Kaplica Karmazynowego Płomienia zbadana', 0),
(12657, 'koKR', 'Potęga Plagi', 'Słuchaj uważnie, rycerzu śmierci, bo przekazuję ci słowa, które rozpoczną wojnę. Wydałem ostateczny wyrok: Śmierć. Im. Wszystkim. Nikt nie przeciwstawi się tak zuchwale potędze Plagi bez odwetu!$B$BSkoro dobrze $gsłużyłeś:służyłaś; mi w pierwszym zadaniu, tak samo posłużysz mi w następnym. Zanieś mój wyrok najwyższemu lordowi Mograine\'owi do punktu dowodzenia Acherusu na pierwszym piętrze. Powiedz mu, by rozpoczął szturm.$B$BA gdy rozprawimy się z Krucjatą, dobijemy Argentowy Brzask.$B', 'Król Lisz rozkazuje ci zanieść jego rozkazy najwyższemu lordowi Darionowi Mograine\'owi w Hebanowej Warowni.$B$BUżyj świecącego teleportu za Królem Liszem, by dotrzeć do najwyższego lorda Dariona Mograine\'a w Sali Dowodzenia.', '', '', '', '', '', '', 0),
(12670, 'koKR', 'Szkarłatne żniwa', 'Pod Acherusem leży Wyłom Śmierci, punkt zborny naszego szturmu na Szkarłatną Krucjatę. Dosiądź jednego z moich gryfów Plagi, które czekają po obu stronach tego podestu, i zamelduj się u księcia Valanara. Rób, co ci każe, a może dożyjesz chwili, gdy te ziemie padną przed nami.', 'Zamelduj się u księcia Valanara w Wyłomie Śmierci.', '', '', '', '', '', '', 0),
(12678, 'koKR', 'Gdy chaos powozi, niech cierpienie trzyma lejce', 'Stawiają teraz opór przed Wyłomem Śmierci i daremnie próbują nas odepchnąć w nadziei, że ocalą swoje konie, kopalnie, drewno i ludzi.$B$BTo będzie twoja pierwsza lekcja wojny w stylu Plagi: TERROR!$B$BUdaj się na linię frontu, na południe stąd, i wybij szkarłatnych krzyżowców. Zostaw ich zwłoki, abyśmy mogli wykorzystać je w marszu śmierci.$B$BAle przede wszystkim: zabijaj uciekających wieśniaków. Na śmierć żołnierzy możemy sobie pozwolić, ale wieśniacy? To właśnie sieje strach w ludzkich sercach.', 'Książę Valanar w Wyłomie Śmierci rozkazuje ci zabić 10 szkarłatnych krzyżowców lub szkarłatnych chłopów oraz 10 mieszkańców Włości Przystani.', '', 'Wróć do księcia Valanara w Wyłomie Śmierci na Plagowiskach: Szkarłatnej Enklawie.', 'Zabici szkarłatni krzyżowcy', 'Zabici mieszkańcy Włości Przystani', '', '', 0),
(12679, 'koKR', 'Dziś wieczorem jemy kolację we Włościach Przystani', 'Zaciemniacze nieba to bezmyślne konstrukty o jednym celu: ZABIJAĆ! A dokładniej: mają zabić każdego mężczyznę i każdą kobietę, którzy uciekają z Włości Przystani, by schronić się w Nowym Avalonie. Nie możemy pozwolić, by ci tchórze dotarli w bezpieczne miejsce, a potem chwycili za broń przeciwko nam!$B$BJest jeden drobny problem. Zaciemniacze używają saronitowych strzał, by uzyskać jak największy zasięg i obrażenia. Saronit to jednak metal występujący tylko w Północnej Grani, więc zapasy są ograniczone! Odzyskaj dla mnie te strzały, a sowicie cię wynagrodzę.', 'Orithos Zaciemniacz Nieba w Wyłomie Śmierci chce, żebyś $godzyskał:odzyskała; 15 saronitowych strzał.', '', 'Wróć do Orithosa Zaciemniacza Nieba w Wyłomie Śmierci na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
(12680, 'koKR', 'Wielka kradzież izabelowatego', 'Cóż za szczęśliwy traf, że Krucjata ma pełną koni stajnię zaledwie rzut kamieniem od tego posterunku. Choć zaciekle jej strzegą, rycerz śmierci z odrobiną inicjatywy mógłby przebić się przez ich obronę i wziąć to, co $gmu:jej; się słusznie należy!$B$BGdy zdobędziesz konia ze Stajni Włości Przystani, przyprowadź go do mnie, a zobaczę, co da się zrobić, by przemienić go w prawdziwego rumaka śmierci.$B$BPamiętaj, $N, to kradzież tylko wtedy, gdy cię złapią. Uważaj na tego obłąkanego stajennego, Kitrika!', 'Salanar Jeździec prosi, żebyś $gukradł:ukradła; konia ze Stajni Włości Przystani i $gprzyprowadził:przyprowadziła; go do niego, do Wyłomu Śmierci.', '', 'Wróć do Salanara Jeźdźca w Wyłomie Śmierci na Plagowiskach: Szkarłatnej Enklawie.', 'Koń skradziony', '', '', '', 0),
(12687, 'koKR', 'Do Królestwa cieni', 'Koń, którego $gukradłeś:ukradłaś;, został zabrany do Królestwa cieni. Tam mój mroczny jeździec zabije zwierzę i wskrzesi je jako rumaka śmierci. Czy starczy ci odwagi, by wejść do Królestwa cieni w pogoni za rumakiem śmierci?$B$BJeśli się zgodzisz, przeniosę cię do świata cieni. Gdy już tam będziesz, odszukaj mrocznego jeźdźca na otwartych polach na południe od nas. Aby zwyciężyć, musisz go zabić, odebrać mu rumaka śmierci i przyprowadzić go do Wyłomu Śmierci. Jeśli ci się uda, użyj Zewu Jeźdźca.', 'Salanar Jeździec z Wyłomu Śmierci wyzwał cię, byś $gzabił:zabiła; Mrocznego Jeźdźca Acherusu i $godebrał:odebrała; mu rumaka śmierci z Acherusu.$B$BJeśli ci się uda, przyprowadź rumaka śmierci z Acherusu do Wyłomu Śmierci i użyj Zewu Jeźdźca, by przywołać Salanara.', 'Wyzwanie Jeźdźca', 'Wróć do Salanara Jeźdźca w Wyłomie Śmierci na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
(12697, 'koKR', 'Gotyk Żniwiarz', 'CHAOS, $N! Krucjata wpadła w popłoch. Ściągnęła wszystkie siły spoza Nowego Avalonu, by postawić blokadę w Punkcie Światłości, na wschód stąd. Desperacko próbują ogołocić Kopalnię Włości Przystani ze wszystkich zasobów i załadować urobek na fregaty zacumowane przy wybrzeżu.$B$BTo co, trochę namieszamy? Gotyk Żniwiarz, wielki nekromanta Króla Lisza, zaszczycił nas swoją obecnością. Ma dla Szkarłatnej Krucjaty pewien prezent. Odszukaj go.', 'Porozmawiaj z Gotykiem Żniwiarzem w Wyłomie Śmierci.', '', '', '', '', '', '', 0),
(12698, 'koKR', 'Prezent, który wciąż daje', 'Przybyłem z zamarzniętego serca Naxxramas, by ucztować na duszach i sprawić naszym zaprzysięgłym wrogom solidne lanie – a dusze właśnie mi się skończyły.$B$BUrządzenie, które zaraz ci dam, to przenośny roznosiciel zarazy. Zanieś je na wschód, do Kopalni Włości Przystani, i uruchom w pobliżu pracujących tam szkarłatnych górników. Zmień górników w ghule i wróć do mnie, gdy będziesz $gmiał:miała; u boku małą armię. Zarezerwowałem dla nich specjalne miejsce w odkurzaczu dusz!', 'Gotyk Żniwiarz z Wyłomu Śmierci dał ci Dar Żniwiarza, którego masz użyć na szkarłatnych górnikach. Stwórz za pomocą urządzenia 5 szkarłatnych ghuli i przyprowadź je do Gotyka.', '', 'Wróć do Gotyka Żniwiarza w Wyłomie Śmierci na Plagowiskach: Szkarłatnej Enklawie.', 'Dostarczone szkarłatne ghule', '', '', '', 0),
(12700, 'koKR', 'Atak okazyjny', 'Rzucają nam wyzwanie już tylko szkarłatne siły w Nowym Avalonie i Punkcie Światłości! Nadszedł czas, by uderzyć na szkarłatną flotę w Punkcie Światłości.$B$BDywersja w kopalni wywołała chaos w ich szeregach. Gorączkowo próbują opuścić teren i wrócić na statki.$B$BTo idealna chwila! Książę Valanar korzysta z okazji, by dobić szkarłatną flotę. Natychmiast się u niego zamelduj!', 'Porozmawiaj z księciem Valanarem w Wyłomie Śmierci.', '', '', '', '', '', '', 0),
(12701, 'koKR', 'Rzeź w Punkcie Światłości', 'W pośpiechu Krucjata popełni jeden fatalny błąd: zapomni sprawdzić wagoniki górnicze.$B$BWróć do Kopalni Włości Przystani, na wschód stąd, i znajdź wagonik, który moje sługi podstawiły przy wychodku. Wejdź do niego, a szkarłatny górnik nieświadomie dopilnuje, byś $gtrafił:trafiła; bezpiecznie za linię wroga.$B$BGdy znajdziesz się na pokładzie jednego z ich statków, obróć przeciw nim ich własne działa! WYRŻNIJ ICH WSZYSTKICH!$B$BGdy będziesz $ggotów:gotowa; do powrotu, przywołaj z działa gryfa Plagi.', 'Książę Valanar w Wyłomie Śmierci rozkazał ci wyrżnąć 100 szkarłatnych defensorów.', '', 'Wróć do księcia Valanara w Wyłomie Śmierci na Plagowiskach: Szkarłatnej Enklawie.', 'Zabici szkarłatni defensorzy', '', '', '', 0),
(12706, 'koKR', 'Zwycięstwo w Wyłomie Śmierci!', '<Książę Valanar wręcza ci zapieczętowany zwój.>$B$BTo pełny raport z naszego zwycięstwa w Wyłomie Śmierci. Masz go dostarczyć najwyższemu lordowi Mograine\'owi – w Acherusie. Zadbałem, by w raporcie znalazły się twoje bohaterskie czyny. Mograine z pewnością sowicie cię za to zwycięstwo wynagrodzi, $N.$B$BIdź już!', 'Dostarcz raport księcia Valanara najwyższemu lordowi Darionowi Mograine\'owi w Acherusie: Hebanowej Warowni.', '', 'Wróć do najwyższego lorda Dariona Mograine\'a w Hebanowej Warowni.', '', '', '', '', 0),
(12711, 'koKR', 'Porzucona poczta', '', '', '', '', '', '', '', '', 0),
(12714, 'koKR', 'Wola Króla Lisza', 'To wola Króla Lisza pcha nas naprzód, $N. Nikt nie zdaje sobie z tego sprawy lepiej niż rycerze śmierci. Samo nasze istnienie jest nierozerwalnie związane z jego świadomością. Z pewnością $gsłyszałeś:słyszałaś;, jak do ciebie przemawia – jak wdziera się w twoje myśli...$B$BSłyszysz go teraz? Może to dla ciebie jeszcze za wcześnie.$B$B<Mograine zamyka oczy i kiwa głową komuś niewidzialnemu.>$B$BTak, mój panie. Stanie się.$B$B$N, masz wrócić do Wyłomu Śmierci i zameldować się u księcia Valanara. Tak rozkazuje Król Lisz!', 'Wróć do Wyłomu Śmierci i zamelduj się u księcia Valanara.', '', '', '', '', '', '', 0),
(12715, 'koKR', 'Krypta Pamięci', 'Rozpoczął się atak na bramy ostatniego bastionu Szkarłatnych. Nasze ghule wykrwawiają linię frontu Krucjaty, a my w tym czasie umacniamy naszą nową wysuniętą bazę, Kryptę Pamięci.$B$BUdaj się na południe do krypty, która graniczy z Nowym Avalonem, i zamelduj się u mojego drogiego brata, księcia Kelesetha.$B$BBędzie na ciebie czekał.$B$BPrzygotuj się, $N, bo zaraz ujrzysz kolejny etap wojny w stylu Plagi: DOMINACJĘ!$B$BJedź już, rycerzu śmierci!', 'Zamelduj się u księcia Kelesetha w Krypcie Pamięci.', '', '', '', '', '', '', 0),
(12716, 'koKR', 'Prośba Siewcy Zarazy', 'Spójrz na tę grządkę dyń! Zauważasz, czego brakuje? Oczywiście, że nie, bo jesteś $gidiotą:idiotką;! Twój mózg pewnie umarł jako pierwszy.$B$B<Nicz wzdycha.>$B$BRozkazano mi zbudować kocioł zarazy. Pomożesz mi.$B$BTuż za bramą Nowego Avalonu jest gospoda. Wejdź do niej i ukradnij pusty kocioł. Potem idź do kuźni, też niedaleko bramy, i ukradnij trochę żelaznych łańcuchów. Przynieś mi to wszystko razem z 10 czaszkami krzyżowców. Czy mam ci też powiedzieć, skąd je wziąć?', 'Nicz Siewca Zarazy poprosił, żebyś $gprzyniósł:przyniosła; mu 1 pusty kocioł, 1 żelazny łańcuch i 10 czaszek krzyżowców.', '', 'Wróć do Nicza Siewcy Zarazy w Tartaku Włości Przystani na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
(12717, 'koKR', 'Specjalny wywar Nicza', 'Kocioł jest gotowy, by zacząć rozsiewać po krainie swoje plugastwo!$B$BA teraz, rycerzu śmierci, krótka lekcja o kotłach zarazy. Gaz, który wydziela kocioł, zabija żywych, ale wzmacnia Plagę. Jak wszystkie twory Plagi żywi się śmiercią i rośnie w siłę, im dłużej się żywi.$B$BWeź te czaszki krzyżowców i wrzuć je do kotła. Wynik bardzo cię ucieszy.', 'Umieść stos czaszek krzyżowców w kotle zarazy.', '', 'Odszukaj kocioł zarazy na Farmach Włości Przystani na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
(12718, 'koKR', 'Więcej czaszek do wywaru', '', '', '', 'Wróć do kotła zarazy na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
(12719, 'koKR', 'Nie ma dokąd uciec ani gdzie się skryć', 'Nic poza całkowitą zagładą nie wystarczy, $N. Dlatego kilkuset bezmyślnych ghuli szturmujących główną bramę Nowego Avalonu to za mało. Musimy przeniknąć do samego serca miasta i pozbyć się ich urzędników. Muszą zobaczyć, że nikt nie wymknie się z uścisku Plagi!$B$BUdaj się do Ratusza Nowego Avalonu, na południowy zachód stąd, i zabij burmistrza. Przeszukaj budynek, znajdź rejestr Nowego Avalonu i przynieś mi go.', 'Książę Keleseth w Krypcie Pamięci rozkazał ci zabić burmistrza Quimby\'ego i zdobyć rejestr Nowego Avalonu.', '', 'Wróć do księcia Kelesetha w Krypcie Pamięci na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
(12720, 'koKR', 'Jak zdobyć przyjaciół i zjednać sobie wrogów', 'Podczas podróży po tym świecie dokonałem kilku interesujących odkryć. Czy wiesz na przykład, że przy odpowiedniej dawce zachęty można wydobyć z człowieka każdą prawdę, jaką ośmiela się ukrywać? Tak się szczęśliwie składa, że mam przy sobie trochę zachęty.$B$B<Keleseth wyjmuje coś z bogato wysadzanej klejnotami szkatułki.>$B$BTo moje „przekonywacze”. Załóż je i ruszaj w pole, rycerzu śmierci. Przyłóż ostre końce do żołnierzy Nowego Avalonu. Dowiedz się prawdy o tym „Karmazynowym Świcie”.', 'Książę Keleseth w Krypcie Pamięci rozkazał ci poznać prawdę o „Karmazynowym Świcie”.$B$BWyjmij przekonywacze Kelesetha z bogato wysadzanej klejnotami szkatułki i użyj ich, by „przekonać” Szkarłatną Krucjatę do mówienia.', '„Karmazynowy Świt” ujawniony', 'Wróć do księcia Kelesetha w Krypcie Pamięci na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
(12722, 'koKR', 'Jak owce na rzeź', 'Większość ludzi uciekłaby, gdy tylko nad ich głowami zawisła nekropolia Plagi. Ale nie Szkarłatna Krucjata!$B$BMuszę przyznać, że dość lubię nasze potyczki z Krucjatą. Przez lata bitwy Plagi z nimi przyniosły kilka najtragiczniejszych wydarzeń w dziejach ludzkości. A jednak oto stoimy – ZNOWU – zwarci w boju!$B$BNie odmawiajmy im rozkoszy wiecznej służby Królowi Liszowi! Wejdź do Nowego Avalonu i spełnij ich życzenie śmierci. Nie zostawiaj nikogo przy życiu.', 'Baron Zerwikrusz w Krypcie Pamięci rozkazał ci zabić 10 żołnierzy Szkarłatnej Krucjaty i 15 mieszkańców Nowego Avalonu.', '', 'Wróć do barona Zerwikrusza w Krypcie Pamięci na Plagowiskach: Szkarłatnej Enklawie.', 'Zabici żołnierze Szkarłatnej Krucjaty', 'Zabici mieszkańcy Nowego Avalonu', '', '', 0),
(12723, 'koKR', 'Za szkarłatnymi liniami', 'Wysłałem Orbaza, Thassariana i Koltirę za linię wroga, by odszukali kuriera. Urządzili bazę wypadową w Szkarłatnej Tawernie, w południowej części Nowego Avalonu. Tawerna jest ukryta za dwoma sadami, obok Kaplicy Karmazynowego Płomienia. Udaj się do tawerny i zamelduj u Orbaza Krwawej Zguby. Powie ci, jak wygląda sytuacja.$B', 'Zamelduj się u Orbaza Krwawej Zguby w Szkarłatnej Tawernie w Nowym Avalonie.', '', '', '', '', '', '', 0),
(12724, 'koKR', 'Ścieżka prawego krzyżowca', 'Nie mamy cholernego pojęcia, kiedy ani gdzie ten kurier ma się pojawić. Żaden z tych ludzi też nie znał odpowiedzi.$B$B<Orbaz wskazuje szkarłatne trupy porozrzucane po podłodze.>$B$BZ ostatniego udało mi się wybić coś przydatnego. W Szkarłatnej Warowni trzymają rozkład wszystkich tras patroli. Chcę, żebyś $gwłamał:włamała; się do warowni i $gukradł:ukradła; ten rozkład.$B$BWarownia to największy budynek w Nowym Avalonie – na północny wschód stąd.', 'Orbaz Krwawa Zguba w Szkarłatnej Tawernie w Nowym Avalonie rozkazał ci ukraść rozkład patroli Nowego Avalonu ze Szkarłatnej Warowni.', '', 'Wróć do Orbaza Krwawej Zguby w Szkarłatnej Tawernie na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
(12725, 'koKR', 'Bracia w śmierci', 'Przebicie się przez szkarłatne linie nie było łatwe. Podczas szturmu ponieśliśmy wiele strat i straciliśmy jednego z naszych najlepszych rycerzy śmierci, Koltirę Tkacza Śmierci. Nie wiem, czy żyje, czy zginął, ale niech mnie piekło pochłonie, jeśli go nie poszukamy.$B$BOstatni raz widziałem, jak zakuwali go w kajdany i wlekli do Szkarłatnej Warowni, na północny wschód stąd. Rozbierz tę twierdzę na kamienie, rycerzu śmierci. Znajdź Koltirę!', 'Odszukaj Koltirę Tkacza Śmierci w Szkarłatnej Warowni.', '', '', '', '', '', '', 0),
(12727, 'koKR', 'Krwawa ucieczka', 'Podniesiono alarm. Nadinkwizytor i jego akolici zaraz tu będą. Jestem zbyt ciężko ranny, by na wiele się przydać, ale zrobię, co w mojej mocy.$B$BZabij nadinkwizytora i jego popleczników. Oderwij mu głowę i zanieś ją Thassarianowi. Zemsta ukoi jego dziką duszę.$B$BJeszcze jedno, $N. Jeśli uda ci się przeżyć i wrócić do Thassariana, powiedz mu, że w kaplicy wykonują egzekucje na więźniach. Może pośle cię tam, byś znów $gzagrał:zagrała; bohatera.', 'Zabij nadinkwizytora Valrotha i zanieś głowę Valrotha Thassarianowi do Szkarłatnej Tawerny w Nowym Avalonie.', '', 'Wróć do Thassariana w Szkarłatnej Tawernie na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
(12733, 'koKR', 'Wyzwanie Śmierci', 'Zrodzone ze zwycięstwa Króla Lisza nad Illidanem Burzogniewnym w sercu mroźnych pustkowi Wyzwanie Śmierci to rytuał przejścia, przez który musi przejść każdy rycerz śmierci.$B$BOdszukaj innych rycerzy śmierci z Acherusu i wyzwij ich na pojedynek. Muszą przyjąć wyzwanie i walczyć, dopóki nie wyłoni się zwycięzca!$B$BIdź już, $N! Zwycięstwo dla Plagi! Chwała Królowi Liszowi!$B', 'Olrun Wzywająca do Boju rozkazała ci wygrać 5 pojedynków z innymi rycerzami śmierci.$B$BMożesz walczyć z nowicjuszami rycerzy śmierci albo z graczami.', '', 'Wróć do Olrun Wzywającej do Boju w Wyłomie Śmierci na Plagowiskach: Szkarłatnej Enklawie.', 'Rycerze śmierci pokonani w pojedynku', '', '', '', 0),
(12738, 'koKR', 'Wołanie o zemstę!', 'Wołanie o zemstę musi zostać wysłuchane, $N. Komandor Zarazopięść i oddział rycerzy śmierci są w drodze, by zrównać z ziemią Kaplicę Karmazynowego Płomienia. Jeśli w kaplicy więzieni są jacyś rycerze śmierci, Zarazopięść ich wyciągnie.$B$BJeśli się pośpieszysz, jeszcze ich dogonisz. Kaplica leży dokładnie na zachód stąd.', 'Zamelduj się u rycerza-komandora Zarazopięści w Kaplicy Karmazynowego Płomienia.', '', '', '', '', '', '', 0),
(12739, 'koKR', 'Wyjątkowa niespodzianka', 'Dotarliśmy tu, rozbiliśmy wszystko w drzazgi i ruszyliśmy do więzienia. Nie spodziewaliśmy się tego, co tam znajdziemy, $N. Wygląda na to, że Krucjata nie próżnowała. Cały budynek jest pełen więźniów Argentowego Brzasku. Większość już nie żyła, kiedy dotarliśmy, ale kilku jeszcze oddychało.$B$BMiałem tam wejść i stracić resztę, ale myślę, że ten zaszczyt powinien przypaść tobie. Zwłaszcza że siedzi tam wyjątkowo zadziorny tauren, którego egzekucja sprawi ci ogromną przyjemność.', 'Rycerz-komandor Zarazopięść w Kaplicy Karmazynowego Płomienia rozkazał ci stracić Malara Dzielnego Roga, więźnia Argentowego Brzasku w pobliskim więzieniu.', '', 'Wróć do rycerza-komandora Zarazopięści w Kaplicy Karmazynowego Płomienia na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
(12742, 'koKR', 'Wyjątkowa niespodzianka', 'Dotarliśmy tu, rozbiliśmy wszystko w drzazgi i ruszyliśmy do więzienia. Nie spodziewaliśmy się tego, co tam znajdziemy, $N. Wygląda na to, że Krucjata nie próżnowała. Cały budynek jest pełen więźniów Argentowego Brzasku. Większość już nie żyła, kiedy dotarliśmy, ale kilku jeszcze oddychało.$B$BMiałem tam wejść i stracić resztę, ale myślę, że ten zaszczyt powinien przypaść tobie. Zwłaszcza że siedzi tam wyjątkowo zadziorna ludzka kobieta, której egzekucja sprawi ci ogromną przyjemność.', 'Rycerz-komandor Zarazopięść w Kaplicy Karmazynowego Płomienia rozkazał ci stracić Ellen Stanbridge, więźniarkę Argentowego Brzasku w pobliskim więzieniu.', '', 'Wróć do rycerza-komandora Zarazopięści w Kaplicy Karmazynowego Płomienia na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
(12743, 'koKR', 'Wyjątkowa niespodzianka', 'Dotarliśmy tu, rozbiliśmy wszystko w drzazgi i ruszyliśmy do więzienia. Nie spodziewaliśmy się tego, co tam znajdziemy, $N. Wygląda na to, że Krucjata nie próżnowała. Cały budynek jest pełen więźniów Argentowego Brzasku. Większość już nie żyła, kiedy dotarliśmy, ale kilku jeszcze oddychało.$B$BMiałem tam wejść i stracić resztę, ale myślę, że ten zaszczyt powinien przypaść tobie. Zwłaszcza że siedzi tam wyjątkowo zadziorna nocna elfka, której egzekucja sprawi ci ogromną przyjemność.', 'Rycerz-komandor Zarazopięść w Kaplicy Karmazynowego Płomienia rozkazał ci stracić Yazminę Dębowy Cierń, więźniarkę Argentowego Brzasku w pobliskim więzieniu.', '', 'Wróć do rycerza-komandora Zarazopięści w Kaplicy Karmazynowego Płomienia na Plagowiskach: Szkarłatnej Enklawie.', '', '', '', '', 0),
