INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1611, 'koKR', '<Strony pokrywają starożytne elfie runy.>\n\nZawarte tu stronice przechowują wspomnienia wydarzeń, które towarzyszyły zbieraniu i tworzeniu odczynników potrzebnych do wykonania mniejszego arkanum.\n\nOby nasi wrogowie nigdy nie zdobyli tych librami.\n\nObym dożył dnia, gdy blade światło księżyca znów rozświetli Quel\'Thalas.\n\nObym umarł jedynie z łaski Kael\'thasa.\n\nObym zabijał na chwałę Illidana.\n\n– Mistrz Kariel Winthalus', 0),
(1630, 'koKR', '<Strony pokrywają starożytne elfie runy.> Zawarte tu stronice przechowują wspomnienia wydarzeń, które towarzyszyły zbieraniu i tworzeniu odczynników potrzebnych do wykonania mniejszego arkanum. Oby nasi wrogowie nigdy nie zdobyli tych librami. Obym dożył dnia, gdy blade światło księżyca znów rozświetli Quel\'Thalas. Obym umarł jedynie z łaski Kael\'thasa. Obym zabijał na chwałę Illidana. – Mistrz Kariel Winthalus ', 0),
(1631, 'koKR', '<Strony pokrywają starożytne elfie runy.>$B$BZawarte tu stronice przechowują wspomnienia wydarzeń, które towarzyszyły zbieraniu i tworzeniu odczynników potrzebnych do wykonania mniejszego arkanum.$B$BOby nasi wrogowie nigdy nie zdobyli tych librami.$B$BObym dożył dnia, gdy blade światło księżyca znów rozświetli Quel\'Thalas.$B$BObym umarł jedynie z łaski Kael\'thasa.$B$BObym zabijał na chwałę Illidana.$B$B– Mistrz Kariel Winthalus', 0),
(1632, 'koKR', '<Strony pokrywają starożytne elfie runy.>\n\nZawarte tu stronice przechowują wspomnienia wydarzeń, które towarzyszyły zbieraniu i tworzeniu odczynników potrzebnych do wykonania mniejszego arkanum.\n\nOby nasi wrogowie nigdy nie zdobyli tych librami. \n\nObym dożył dnia, gdy blade światło księżyca znów rozświetli Quel\'Thalas.\n\nObym umarł jedynie z łaski Kael\'thasa.\n\nObym zabijał na chwałę Illidana.\n\n– Mistrz Kariel Winthalus', 0),
(1633, 'koKR', '<Strony pokrywają starożytne elfie runy.> Zawarte tu stronice przechowują wspomnienia wydarzeń, które towarzyszyły zbieraniu i tworzeniu odczynników potrzebnych do wykonania mniejszego arkanum. Oby nasi wrogowie nigdy nie zdobyli tych librami. Obym dożył dnia, gdy blade światło księżyca znów rozświetli Quel\'Thalas. Obym umarł jedynie z łaski Kael\'thasa. Obym zabijał na chwałę Illidana. – Mistrz Kariel Winthalus ', 0),
