(29403, 'koKR', 'Ty przyjść dokończyć robota, mon?', 'Ty przyjść dokończyć robota, mon?', 0),
(29404, 'koKR', 'Ten troll chcieć stać, kiedy...', 'Ten troll chcieć stać, kiedy...', 0),
(29405, 'koKR', '$n? Mon?', '$n? Mon?', 0),
(29406, 'koKR', '$n, ja wszędzie poznać te kły... Co... Co oni z tobą zrobić, mon?', '$n, ja wszędzie poznać te kły... Co... Co oni z tobą zrobić, mon?', 0),
(29407, 'koKR', 'Ty mnie nie pamiętać, mon? Niech szlag trafi Plaga! Oni chcieć wyssać z ciebie wszystko, co robić z ciebie mistrz mojo. Każda ostatnia kropla dobra... Wszystko, co robić z ciebie trollowy bohater, mon!', 'Ty mnie nie pamiętać, mon? Niech szlag trafi Plaga! Oni chcieć wyssać z ciebie wszystko, co robić z ciebie mistrz mojo. Każda ostatnia kropla dobra... Wszystko, co robić z ciebie trollowy bohater, mon!', 0),
(29408, 'koKR', 'MYŚL, $n. Myśl wstecz, mon! My być Mroczna Włócznia, mon! Bracia i siostry! Ty pamiętać, jak my walczyć z Zalazane i ściąć mu głowa i uwolnić Wyspy Echa? MON! MYŚL! Ty być czempion trolli Mrocznej Włóczni!\n', 'MYŚL, $n. Myśl wstecz, mon! My być Mroczna Włócznia, mon! Bracia i siostry! Ty pamiętać, jak my walczyć z Zalazane i ściąć mu głowa i uwolnić Wyspy Echa? MON! MYŚL! Ty być czempion trolli Mrocznej Włóczni!', 0),
(29409, 'koKR', 'Słuchaj mnie, $gbracie:siostro;. Ty musieć walczyć z władza Króla Lisza. On być potwór, co chcieć widzieć ten świat – nasz świat – w ruina. Nie dać mu użyć ciebie do jego celów. Ty być bohater kiedyś i ty być bohater znowu! Walcz, mon! Walcz z jego władza!', 'Słuchaj mnie, $gbracie:siostro;. Ty musieć walczyć z władza Króla Lisza. On być potwór, co chcieć widzieć ten świat – nasz świat – w ruina. Nie dać mu użyć ciebie do jego celów. Ty być bohater kiedyś i ty być bohater znowu! Walcz, mon! Walcz z jego władza!', 0),
(29410, 'koKR', 'Już... Już nie ma dla mnie czasu. Ja być skończony. Dobij mnie, $n. Zrób to, albo oni zabić ciebie i mnie. $n... Pamiętać Wioska Sen\'jin, mon! Ten świat być wart ratowania!', 'Już... Już nie ma dla mnie czasu. Ja być skończony. Dobij mnie, $n. Zrób to, albo oni zabić ciebie i mnie. $n... Pamiętać Wioska Sen\'jin, mon! Ten świat być wart ratowania!', 0),
(29411, 'koKR', 'Zrób to, $n! Skróć moja męka!', 'Zrób to, $n! Skróć moja męka!', 0),
(29412, 'koKR', '%s umiera z powodu odniesionych ran.', '%s umiera z powodu odniesionych ran.', 0),
