(29444, 'koKR', 'Jesteśmy wybrańcami, $n. Rycerzami śmierci Plagi, posłanymi, by siać zniszczenie w imię naszego pana.', '', 0),
(29445, 'koKR', '$GPrzegapiłem:Przegapiłam; bramę do Acherusu, Orbazie. Czy możesz otworzyć kolejną?', '$GPrzegapiłem:Przegapiłam; bramę do Acherusu, Orbazie. Czy możesz otworzyć kolejną?', 0),
