(29503, 'koKR', 'To koniec!', '', 0),
(29504, 'koKR', 'Złupienie Szkarłatnej Enklawy przejdzie do historii jako przestroga!', '', 0),
(29505, 'koKR', 'Nie ma dokąd uciec...', '', 0),
(29506, 'koKR', 'Niech zniszczenie tego miejsca będzie nauczką dla wszystkich, którzy ośmielą się przeciwstawić Pladze!', '', 0),
(29508, 'koKR', 'Nie zostawiać nikogo przy życiu!', '', 0),
(29509, 'koKR', 'Wkrótce będziecie należeć do Plagi.', '', 0),
(29510, 'koKR', 'Gdzie teraz jest wasza Światłość, krzyżowcy?', '', 0),
(29511, 'koKR', 'Pokłońcie się swojemu królowi!', '', 0),
(29512, 'koKR', 'Światłość was opuściła!', '', 0),
(29513, 'koKR', 'Nie ma Światłości. Jest tylko ciemność!', '', 0),
(29514, 'koKR', 'Przyjdźcie do mnie, krzyżowcy. Stworzę was na nowo!', '', 0),
