(29641, 'koKR', 'B... Będzie bolało?', 'B... Będzie bolało?', 0),
(29642, 'koKR', 'Mrowi...', 'Mrowi...', 0),
(29643, 'koKR', 'Czy jest za późno, żebym zmienił zdanie? Może po prostu mnie zabijesz?', 'Czy jest za późno, żebym zmienił zdanie? Może po prostu mnie zabijesz?', 0),
(29644, 'koKR', 'Jesteś potworem!', 'Jesteś potworem!', 0),
(29645, 'koKR', 'Błagam! Oszczędź mnie! Ja...', 'Błagam! Oszczędź mnie! Ja...', 0),
(29646, 'koKR', 'Co za koszmar! KOSZMAR!!', 'Co za koszmar! KOSZMAR!!', 0),
(29648, 'koKR', 'Po tym poznasz, że działa.', '', 0),
(29649, 'koKR', 'PRZECIEŻ cię zabiję. Po co ten pośpiech?', '', 0),
(29650, 'koKR', 'Pochlebstwa nic ci nie dadzą.', '', 0),
(29651, 'koKR', 'Nie bądź śmieszny. Dokąd byś w ogóle poszedł, gdybym cię oszczędził? Właśnie skończyliśmy wybijać twoją cywilizację. Pamiętasz?', '', 0),
(29690, 'koKR', 'Tu poświęciłem wszystko, by uwolnić ojca. Teraz przybywam, by to zniszczyć...', '', 0),
(29691, 'koKR', 'Jestem $ggotów:gotowa;, najwyższy lordzie. Niech rozpocznie się oblężenie Świetlistej Nadziei!', 'Jestem $ggotów:gotowa;, najwyższy lordzie. Niech rozpocznie się oblężenie Świetlistej Nadziei!', 0),
(29694, 'koKR', 'Żołnierze Plagi, w gotowości! Przygotujcie się, by rozpętać swą furię na Argentowy Brzask!', '', 0),
(29696, 'koKR', 'Niebo płacze nad wspaniałym spustoszeniem tych ziem! Wkrótce spłyną na nas daremne łzy Azeroth!', 'Niebo płacze nad wspaniałym spustoszeniem tych ziem! Wkrótce spłyną na nas daremne łzy Azeroth!', 0),
(29697, 'koKR', 'Rycerze śmierci z Acherusu, marsz śmierci się rozpoczyna!', 'Rycerze śmierci z Acherusu, marsz śmierci się rozpoczyna!', 0),
(29699, 'koKR', 'Żołnierze Plagi, rycerze śmierci z Acherusu, sługi ciemności: usłyszcie wezwanie najwyższego lorda!', 'Żołnierze Plagi, rycerze śmierci z Acherusu, sługi ciemności: usłyszcie wezwanie najwyższego lorda!', 0),
(29703, 'koKR', 'Tu poświęciłem wszystko, by uwolnić ojca. Teraz przybywam, by to zniszczyć...', '', 0),
(29713, 'koKR', 'Nie ma dla ciebie miejsca na tych ziemiach, potworze!', 'Nie ma dla ciebie miejsca na tych ziemiach, potworze!', 0),
(29714, 'koKR', 'Niech rozpocznie się oczyszczanie!', 'Niech rozpocznie się oczyszczanie!', 0),
(29715, 'koKR', 'Niech Światłość cię oczyści!', 'Niech Światłość cię oczyści!', 0),
(29716, 'koKR', 'Plugawy pomiot Plagi! GIŃ!', 'Plugawy pomiot Plagi! GIŃ!', 0),
(29717, 'koKR', 'Krucjata zwycięży!', 'Krucjata zwycięży!', 0),
(29719, 'koKR', 'Nie ma dla ciebie miejsca na tych ziemiach, potworze!', 'Nie ma dla ciebie miejsca na tych ziemiach, potworze!', 0),
(29720, 'koKR', 'Niech rozpocznie się oczyszczanie!', 'Niech rozpocznie się oczyszczanie!', 0),
(29722, 'koKR', 'Niebo czerwieni się od krwi poległych! Król Lisz czuwa nad nami, sługi! Zostawcie za sobą tylko popioły i niedolę!', 'Niebo czerwieni się od krwi poległych! Król Lisz czuwa nad nami, sługi! Zostawcie za sobą tylko popioły i niedolę!', 0),
(29727, 'koKR', 'Klęknijcie przed najwyższym lordem!', '', 0),
(29728, 'koKR', 'Nie macie szans!', '', 0),
(29729, 'koKR', 'Plaga zniszczy to miejsce!', '', 0),
(29731, 'koKR', 'Życie bez cierpienia nie ma sensu!', '', 0),
(29732, 'koKR', 'Jak długo jeszcze wytrzymają wasze siły?', '', 0),
(29733, 'koKR', 'Z Argentowym Brzaskiem koniec!', '', 0),
(29734, 'koKR', 'Nikogo nie oszczędzać!', '', 0),
(29735, 'koKR', 'Co to ma być?! Mój... Nie mogę uderzyć...', '', 0),
(29736, 'koKR', 'SŁUCHAJ MNIE, OSTRZE!', '', 0),
(29737, 'koKR', 'Zrobisz, co ci rozkażę! To ja tu rządzę!', '', 0),
(29738, 'koKR', 'Ja... nie mogę... Ostrze ze mną walczy...', '', 0),
(29739, 'koKR', 'Co się ze mną dzieje?', '', 0),
(29740, 'koKR', 'Moc... słabnie...', '', 0),
(29741, 'koKR', 'Spopielacz mi się sprzeciwia...', '', 0),
(29742, 'koKR', 'Sługi, na pomoc!', '', 0),
(29759, 'koKR', '%s klęka pokonany przed Tirionem Fordringiem.', '', 0),
(29760, 'koKR', 'Odstąpcie, rycerze śmierci. Przegraliśmy. Światłość... to miejsce... nie ma nadziei...', '', 0),
(29761, 'koKR', 'Oszczędzaj oddech, starcze. To może być ostatni, jaki weźmiesz.', '', 0),
(29767, 'koKR', 'Ojcze!', '', 0),
(29768, 'koKR', 'Argh... co... to...', '', 0),
(29781, 'koKR', 'Ty... zdradziłeś mnie. Zdradziłeś nas wszystkich, potworze! Zmierz się z potęgą Mograine\'a!', '', 0),
(29782, 'koKR', 'Żałosne...', '', 0),
(29801, 'koKR', 'Tirionie!', '', 0),
(29802, 'koKR', '%s osuwa się na ziemię.', '', 0),
(29824, 'koKR', 'Ten dzień jeszcze nie nadszedł...', '', 0),
(29851, 'koKR', 'Tak samo Rycerze Hebanowego Miecza. Choć dla naszego rodzaju nie ma miejsca w waszym świecie, będziemy walczyć, by położyć kres Królowi Liszowi. Przysięgam!', '', 0),
(29867, 'koKR', 'Jako uczniowie krwi dążycie do opanowania samej siły życiowej waszych wrogów.', '', 0),
(29868, 'koKR', 'Czy to ostrzem, czy zaklęciem – krew zasila nasze ataki i osłabia naszych wrogów.', '', 0),
(29869, 'koKR', 'Prawdziwi mistrzowie uczą się sprawiać, by krew służyła czemuś więcej niż tylko ich sile w walce.', '', 0),
(29870, 'koKR', 'Wysysanie energii z wrogów, zarówno walczących, jak i poległych, pozwala nam trwać tam, gdzie słabsze istoty padają z wyczerpania.', '', 0),
(29871, 'koKR', 'A każdy wróg, który pada wyssany i ograbiony z energii, tylko mocniej napędza nasz szturm.', '', 0),
(29872, 'koKR', 'Jako mistrzowie krwi znamy walkę bez końca...', '', 0),
(29873, 'koKR', 'Znamy głód, którego nie da się zaspokoić...', '', 0),
(29874, 'koKR', 'Znamy moc, której nie da się pokonać...', '', 0),
(29875, 'koKR', 'Jako mistrzowie krwi jesteśmy panami samego życia i śmierci. Wobec nas nawet nadzieja pada wyssana i martwa.', '', 0),
(30172, 'koKR', 'Tysiąc tysięcy żywotów poświęcę dla ciebie, mój panie.', 'Tysiąc tysięcy żywotów poświęcę dla ciebie, mój panie.', 0),
(30173, 'koKR', 'Jestem na twoje rozkazy, mój królu!', 'Jestem na twoje rozkazy, mój królu!', 0),
(30174, 'koKR', 'Mój królu, świat zadrży z czci...', 'Mój królu, świat zadrży z czci...', 0),
(30175, 'koKR', 'Jestem narzędziem twojego zniszczenia, mój królu! Rozkazuj mi!', 'Jestem narzędziem twojego zniszczenia, mój królu! Rozkazuj mi!', 0),
(30176, 'koKR', 'Biada tym, którzy ośmielą się przeciwstawić Pladze!', 'Biada tym, którzy ośmielą się przeciwstawić Pladze!', 0),
(30177, 'koKR', 'Nasi wrogowie zostaną unicestwieni!', 'Nasi wrogowie zostaną unicestwieni!', 0),
(30179, 'koKR', 'Odrodziłam się, mój królu, tylko po to, by ci służyć.', 'Odrodziłam się, mój królu, tylko po to, by ci służyć.', 0),
(30180, 'koKR', 'Nie będzie ocalałych, mój panie.', 'Nie będzie ocalałych, mój panie.', 0),
(30204, 'koKR', 'Przeżyć może tylko jeden!', 'Przeżyć może tylko jeden!', 0),
(30205, 'koKR', 'A teraz zginiesz!', 'A teraz zginiesz!', 0),
(30207, 'koKR', 'Wywalczę sobie wolność i opuszczę to przeklęte miejsce!', 'Wywalczę sobie wolność i opuszczę to przeklęte miejsce!', 0),
(30208, 'koKR', 'Twój błąd zaprowadzi cię do grobu, potworze!', 'Twój błąd zaprowadzi cię do grobu, potworze!', 0),
(30209, 'koKR', 'Uznają mnie za niegodnego? Pokażę im niegodnego!', 'Uznają mnie za niegodnego? Pokażę im niegodnego!', 0),
